1	package api
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/url"
9		"strings"
10	
11		"github.com/gin-gonic/gin"
12	
13		"github.com/xjeey8iust/sen-incident-response-flow/internal/store"
14	)
15	
16	var validSeverities = map[string]bool{
17		"low":      true,
18		"medium":   true,
19		"high":     true,
20		"critical": true,
21	}
22	
23	var validStages = map[string]bool{
24		"受理": true,
25		"遏制": true,
26		"清除": true,
27		"恢复": true,
28		"关闭": true,
29	}
30	
31	// NewRouter wires the public HTTP surface. The service contract in README.md
32	// describes the error shape every entry must keep.
33	func NewRouter(st *store.Store) *gin.Engine {
34		gin.SetMode(gin.ReleaseMode)
35		router := gin.New()
36		router.Use(gin.Recovery())
37	
38		router.GET("/healthz", func(c *gin.Context) {
39			if err := st.Ping(); err != nil {
40				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
41				return
42			}
43			c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
44		})
45	
46		router.POST("/incidents", createIncident(st))
47		router.GET("/incidents", queryIncidents(st))
48	
49		router.NoRoute(func(c *gin.Context) {
50			writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
51		})
52		return router
53	}
54	
55	// registerRequest mirrors the accepted registration body. Pointer fields let
56	// the handler reject missing keys and explicit nulls alike.
57	type registerRequest struct {
58		ID       *string   `json:"id"`
59		Severity *string   `json:"severity"`
60		Assets   *[]string `json:"assets"`
61		Owner    *string   `json:"owner"`
62	}
63	
64	// registerFields is the case-sensitive whitelist of accepted registration
65	// fields. Names are compared after JSON unescaping, so "id" is accepted
66	// while "ID" is an unknown field.
67	var registerFields = map[string]bool{
68		"id":       true,
69		"severity": true,
70		"assets":   true,
71		"owner":    true,
72	}
73	
74	func createIncident(st *store.Store) gin.HandlerFunc {
75		return func(c *gin.Context) {
76			payload, ok := decodeRegisterRequest(c.Request.Body)
77			if !ok || !payload.valid() {
78				writeInvalidRequest(c)
79				return
80			}
81	
82			incident, err := st.Register(*payload.ID, *payload.Severity, *payload.Owner, *payload.Assets)
83			if errors.Is(err, store.ErrIncidentConflict) {
84				writeError(c, http.StatusConflict, "incident_conflict", "incident id is already registered with different attributes")
85				return
86			}
87			if err != nil {
88				writeError(c, http.StatusServiceUnavailable, "storage_unavailable", "database is not available")
89				return
90			}
91			c.JSON(http.StatusCreated, incident)
92		}
93	}
94	
95	// decodeRegisterRequest parses the registration body token by token so the
96	// field whitelist stays case-sensitive and duplicate keys are rejected.
97	// encoding/json's struct decoding cannot do either: it matches tags
98	// case-insensitively and silently lets a later key overwrite an earlier one.
99	// Keys arrive already unescaped, so "id" collides with "id" while
100	// case variants like "ID" fall outside the whitelist.
101	func decodeRegisterRequest(body io.Reader) (registerRequest, bool) {
102		var payload registerRequest
103		decoder := json.NewDecoder(body)
104		token, err := decoder.Token()
105		if err != nil {
106			return payload, false
107		}
108		if delim, ok := token.(json.Delim); !ok || delim != '{' {
109			return payload, false
110		}
111		seen := map[string]bool{}
112		for decoder.More() {
113			token, err := decoder.Token()
114			if err != nil {
115				return payload, false
116			}
117			key, ok := token.(string)
118			if !ok || !registerFields[key] || seen[key] {
119				return payload, false
120			}
121			seen[key] = true
122			var decodeErr error
123			switch key {
124			case "id":
125				decodeErr = decoder.Decode(&payload.ID)
126			case "severity":
127				decodeErr = decoder.Decode(&payload.Severity)
128			case "assets":
129				decodeErr = decoder.Decode(&payload.Assets)
130			case "owner":
131				decodeErr = decoder.Decode(&payload.Owner)
132			}
133			if decodeErr != nil {
134				return payload, false
135			}
136		}
137		if _, err := decoder.Token(); err != nil {
138			return payload, false
139		}
140		if err := decoder.Decode(&struct{}{}); err != io.EOF {
141			return payload, false
142		}
143		return payload, true
144	}
145	
146	// valid reports whether every required field is present and well formed.
147	func (r *registerRequest) valid() bool {
148		if r.ID == nil || strings.TrimSpace(*r.ID) == "" {
149			return false
150		}
151		if r.Severity == nil || !validSeverities[*r.Severity] {
152			return false
153		}
154		if r.Owner == nil || strings.TrimSpace(*r.Owner) == "" {
155			return false
156		}
157		if r.Assets == nil || len(*r.Assets) == 0 {
158			return false
159		}
160		for _, asset := range *r.Assets {
161			if strings.TrimSpace(asset) == "" {
162				return false
163			}
164		}
165		return true
166	}
167	
