        seen[key] = true
        var raw json.RawMessage
        if err := decoder.Decode(&raw); err != nil { return nil, false }
        values[key] = raw
    }
    if _, err := decoder.Token(); err != nil { return nil, false }
    if err := decoder.Decode(&struct{}{}); err != io.EOF { return nil, false }
    return values, true
}
